parameters.jsCode:
const raw = $input.first()?.json || {};
const webhookEvent = $('Webhook').item?.json?.body?.events?.[0] || {};
const userId = webhookEvent.source?.userId || '';
const replyToken = webhookEvent.replyToken || '';
const userMessage = (webhookEvent.message?.text || "").trim();

// -------------------------------------------------------------
// 1. ดักจับข้อความจาก Rich Menu หรือคีย์เวิร์ดตรงๆ
// -------------------------------------------------------------
if (userMessage.includes("ดูตารางนัด") || userMessage.includes("นัดหมายทั้งหมด") || userMessage.includes("ตารางนัด") || userMessage.includes("เช็กนัด")) {
  return [{ json: { route: 'view_appointments', userId, replyToken } }];
}
if (userMessage.includes("นัดหมายที่กำลังจะมาถึง") || userMessage.includes("นัดต่อไป") || userMessage.includes("นัดเร็วๆ นี้")) {
  return [{ json: { route: 'view_upcoming', userId, replyToken } }];
}
if (userMessage.includes("บันทึกนัดใหม่") || userMessage.includes("สร้างนัดใหม่")) {
  return [{ 
    json: { 
      route: 'new_prompt', 
      userId, 
      replyToken,
      replyMessage: {
        type: "text",
        text: "🦉 ฮูกก! อยากบันทึกนัดอะไร พิมพ์บอกเวลาและรายละเอียดมาได้เลยนะฮะ\n\n💡 ตัวอย่างเช่น:\n- 'พรุ่งนี้ 9 โมง ประชุมกับเพื่อน'\n- 'วันที่ 20 ก.ย. บ่ายโมง เข้าประชุมสาขา'"
      }
    } 
  }];
}
if (userMessage.includes("สถิติของฉัน") || userMessage.includes("ดูสถิติ")) {
  return [{ json: { route: 'view_profile', userId, replyToken } }];
}
if (userMessage.includes("วิธีใช้งาน") || userMessage.includes("คู่มือ")) {
  return [{ json: { route: 'view_help', userId, replyToken } }];
}
if (userMessage.includes("ข้อมูลส่วนบุคคล") || userMessage.includes("ตั้งค่า")) {
  return [{ json: { route: 'view_settings', userId, replyToken } }];
}

// -------------------------------------------------------------
// 2. ถอดรหัส JSON จาก AI Gemini
// -------------------------------------------------------------
let textToParse = raw.text || raw.content?.parts?.[0]?.text || raw.response?.text || (typeof raw === 'string' ? raw : JSON.stringify(raw));

let aiData = {};
try {
  const cleanText = textToParse.replace(/```json/gi, '').replace(/```/g, '').trim();
  aiData = JSON.parse(cleanText);
} catch (e) {
  aiData = { 
    route: "chat", 
    is_appointment: false, 
    reply_message: "ฮูกก! นัดดีอ่านข้อความนี้ไม่ค่อยเข้าใจ ลองพิมพ์บอกเวลาและกิจกรรมใหม่อีกทีนะ 🦉" 
  };
}

// -------------------------------------------------------------
// 3. กระจายงานตาม Route ทั่วไป
// -------------------------------------------------------------
if (aiData.route === 'view_appointments') return [{ json: { route: 'view_appointments', userId, replyToken } }];
if (aiData.route === 'view_upcoming') return [{ json: { route: 'view_upcoming', userId, replyToken } }];
if (aiData.route === 'view_profile') return [{ json: { route: 'view_profile', userId, replyToken } }];
if (aiData.route === 'view_help') return [{ json: { route: 'view_help', userId, replyToken } }];
if (aiData.route === 'view_settings') return [{ json: { route: 'view_settings', userId, replyToken } }];

// ตรวจสอบความสมบูรณ์ของนัดหมาย
const eventTitle = String(aiData.event || aiData.title || "").trim();
const dt = String(aiData.datetime || aiData.dateTime || "").trim();
const isValidSchedule = Boolean(aiData.is_appointment && dt && dt.length >= 10 && eventTitle);

// เคส: นัดหมายเดิม/ซ้ำ
if (aiData.route === 'นัดซ้ำ' || aiData.is_duplicate === true) {
  return [{
    json: {
      route: 'duplicate',
      userId: userId,
      replyToken: replyToken,
      replyMessage: {
        type: "text",
        text: `⚠️ ฮูกก! นัดหมาย "${eventTitle}" ในเวลา ${dt} น. คุณเคยบันทึกไว้ในระบบแล้วนะฮะ 🦉✨`
      }
    }
  }];
}

// เคส: คุยเล่น / พิมพ์มั่ว / ข้อมูลไม่ครบ -> แนบ Quick Reply ดึงกลับเข้าสู่ Flow
if (!isValidSchedule) {
  return [{
    json: {
      route: 'chat',
      userId: userId,
      replyToken: replyToken,
      replyMessage: {
        type: "text",
        text: aiData.reply_message || "🦉 ฮูกก! นัดดีช่วยบันทึกกิจกรรมและเตือนความจำนะฮะ ถ้ามีธุระพิมพ์บอกเวลาและสิ่งที่ต้องทำมาได้เลยน้า ✨",
        quickReply: {
          items: [
            {
              type: "action",
              action: {
                type: "uri",
                label: "📅 เปิดตารางนัด",
                uri: "https://liff.line.me/2011350023-z3qS09LJ"
              }
            },
            {
              type: "action",
              action: {
                type: "uri",
                label: "💡 วิธีใช้งาน",
                uri: "https://liff.line.me/2011350023-m6M2rxLv"
              }
            },
            {
              type: "action",
              action: {
                type: "message",
                label: "✍️ บันทึกนัดหมายใหม่",
                text: "บันทึกนัดหมายใหม่"
              }
            }
          ]
        }
      }
    }
  }];
}

// -------------------------------------------------------------
// 4. สกัดนัดหมายสำเร็จ -> ส่งต่อข้อมูลดิบให้ Timezone Generator ทันที
// -------------------------------------------------------------
return [{
  json: {
    route: 'new',
    userId: userId,
    replyToken: replyToken,
    event: eventTitle,
    datetime: dt,
    endDatetime: String(aiData.endDatetime || dt).trim(),
    location: String(aiData.location && aiData.location !== '-' ? aiData.location : '-').trim(),
    category: String(aiData.category || 'ทั่วไป').trim()
  }
}];

const event = $json.body?.events?.[0] || {};
const postback = event.postback || {};
const dataStr = postback.data || '';

// แยก Query String ด้วย JavaScript พื้นฐาน
const params = {};
if (dataStr) {
  dataStr.split('&').forEach(pair => {
    const [key, val] = pair.split('=');
    if (key) params[key] = decodeURIComponent(val || '');
  });
}

// ดึงเวลาใหม่กรณีเป็นการกดเลื่อนนัดหมาย (datetimepicker)
let newDatetime = null;
if (postback.params && postback.params.datetime) {
  newDatetime = postback.params.datetime.replace('T', ' ');
}

return [{
  json: {
    action: params.action || '',
    eventId: params.eventId || '',
    newDatetime: newDatetime,
    replyToken: event.replyToken,
    userId: event.source?.userId
  }
}];

