const items = $('view_upcoming').all();
const webhookEvent = $('Webhook').item?.json?.body?.events?.[0] || {};
const replyToken = webhookEvent.replyToken || '';
const now = new Date();

// กรณีไม่พบนัดหมายที่กำลังจะมาถึง
if (!items || items.length === 0 || !items[0].json?.event) {
  return [{
    json: {
      replyToken: replyToken,
      messages: [
        {
          type: "text",
          text: "🦉 ฮูกก! ตอนนี้คุณยังไม่มีนัดหมายที่กำลังจะมาถึงเลยครับ พักผ่อนให้สบายใจได้เลย ✨"
        }
      ]
    }
  }];
}

// ฟังก์ชันตัดแต่ง String วันเวลา ป้องกันเวลาเพี้ยน
function formatCleanDateTime(dtVal) {
  if (!dtVal) return '-';
  const str = String(dtVal).replace('T', ' ').trim();
  return str.substring(0, 16); // ได้ 'YYYY-MM-DD HH:mm' แน่นอน
}

// ฟังก์ชันคำนวณสถานะ / เวลานับถอยหลัง (ล็อกเขตเวลาไทย +07:00)
function formatStatus(status, datetimeStr) {
  if (status === 'done') {
    return { text: 'เสร็จสิ้น', badgeBg: '#E0E0E0', textColor: '#666666' };
  }

  if (!datetimeStr) {
    return { text: status || 'รอดำเนินการ', badgeBg: '#E8F5E9', textColor: '#2E7D32' };
  }

  // แปลงให้เป็น Date Object แบบล็อกเวลาไทย (+07:00) ชัดเจน
  const cleanStr = formatCleanDateTime(datetimeStr).replace(' ', 'T');
  const targetDate = new Date(`${cleanStr}:00+07:00`);
  const diffMs = targetDate.getTime() - now.getTime();

  if (isNaN(diffMs)) {
    return { text: status || 'active', badgeBg: '#E8F5E9', textColor: '#2E7D32' };
  }

  if (diffMs < 0) {
    return { text: 'เลยเวลานัดแล้ว', badgeBg: '#F3F4F6', textColor: '#9CA3AF' };
  }

  const diffMinutes = Math.floor(diffMs / (1000 * 60));
  const diffHours = Math.floor(diffMinutes / 60);
  const diffDays = Math.floor(diffHours / 24);

  let timeText = '';
  if (diffDays > 0) {
    const remainHours = diffHours % 24;
    timeText = `อีก ${diffDays} วัน ${remainHours > 0 ? remainHours + ' ชม.' : ''}`;
