    const remainMins = diffMinutes % 60;
    timeText = `อีก ${diffHours} ชม. ${remainMins > 0 ? remainMins + ' น.' : ''}`;
  } else {
    timeText = `อีก ${Math.max(1, diffMinutes)} นาที`;
  }

  return { text: timeText, badgeBg: '#E8F5E9', textColor: '#2E7D32' };
}

