const items = $input.all();
const now = new Date();
const next7Days = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

// กรอง Object เปล่าออก
const validItems = items.filter(item => {
  const row = item.json;
  return row && (row.event || row.datetime || row.location || row.title || row.category);
});

let total = validItems.length;
let done = 0;
let upcoming = 0;
let cancelled = 0;

const categories = {};
const dayLabels = ['จันทร์', 'อังคาร', 'พุธ', 'พฤหัสบดี', 'ศุกร์', 'เสาร์', 'อาทิตย์'];
const overallCounts = [0, 0, 0, 0, 0, 0, 0];
const weeklyCounts = [0, 0, 0, 0, 0, 0, 0];

for (const item of validItems) {
  const row = item.json;
  const status = (row.status || '').toLowerCase().trim();
  const dtStr = row.datetime ? String(row.datetime).replace(' ', 'T') : null;
  const dt = dtStr ? new Date(dtStr) : null;
  const isValidDate = dt && !isNaN(dt.getTime());

  // 1. แยกสถานะ
  if (status === 'done') {
    done++;
  } else if (status === 'cancelled' || status === 'ยกเลิก' || (isValidDate && dt < now)) {
    cancelled++;
  } else {
    upcoming++;
  }

  // 2. หมวดหมู่
  const cat = row.category || 'ทั่วไป';
  categories[cat] = (categories[cat] || 0) + 1;

  // 3. นับสถิติตามวันในสัปดาห์
  if (isValidDate) {
    let dayIdx = dt.getDay() - 1;
    if (dayIdx === -1) dayIdx = 6; // แปลงวันอาทิตย์ไป index 6

    // สถิติภาพรวมลูปชีวิต
    overallCounts[dayIdx]++;

    // สถิติ 7 วันข้างหน้า (นับเฉพาะงานที่ยังไม่เสร็จ/ยังไม่ยกเลิก)
    if (dt >= now && dt <= next7Days && status !== 'done' && status !== 'cancelled' && status !== 'ยกเลิก') {
      weeklyCounts[dayIdx]++;
    }
  }
}

// สร้างคำแนะนำภาพรวม
let overallAdvice = 'ตารางเวลาของคุณกระจายตัวได้ดีมาก ไม่มีวันไหนที่แน่นเกินไปครับ';
if (total === 0) {
  overallAdvice = '🦉 ตอนนี้ยังไม่มีนัดหมายในระบบ เริ่มต้นสร้างนัดแรกกับน้องนัดดีได้เลยครับ';
} else {
  const maxOverall = Math.max(...overallCounts);
  if (maxOverall >= 3) {
    const busyDay = dayLabels[overallCounts.indexOf(maxOverall)];
    overallAdvice = `💡 <b>วัน${busyDay}</b> คือวันด่านหินของคุณ! (มีงานสะสมถึง ${maxOverall} รายการ) ควรวางแผนหรือเคลียร์งานล่วงหน้านะครับ`;
  }
}

// สร้างคำแนะนำ 7 วันข้างหน้า
const maxWeekly = Math.max(...weeklyCounts);
let weeklyAdvice = '🎉 7 วันข้างหน้านี้ตารางของคุณโล่งมาก ไม่มีนัดหมายที่ต้องกังวลเลย!';
if (maxWeekly > 0) {
  const busyWeeklyDay = dayLabels[weeklyCounts.indexOf(maxWeekly)];
  weeklyAdvice = `⚡ ใน 7 วันข้างหน้า วันที่งานแน่นที่สุดคือ <b>วัน${busyWeeklyDay}</b> (${maxWeekly} รายการ) อย่าลืมเตรียมพร้อมล่วงหน้านะครับ`;
}

return {
  json: {
    status: "success",
    data: {
      summary: { total, done, upcoming, cancelled },
      categories,
      traffic: {
        labels: dayLabels,
        overall: overallCounts,
        weekly: weeklyCounts
      },
      advice: {
        overall: overallAdvice,
        weekly: weeklyAdvice
      }
    }
  }
};

