function generateUUIDv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0;
    var v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

function parseThaiDateTime(str) {
  if (!str) return new Date();
  var clean = String(str).replace(' ', 'T');
  var withZone = (clean.indexOf('+') !== -1 || clean.indexOf('Z') !== -1)
    ? clean 
    : clean + ':00+07:00';
  var d = new Date(withZone);
  return isNaN(d.getTime()) ? new Date() : d;
}

return $input.all().map(function(item) {
  var data = item.json || {};

  var eventTitle = String(data.event || data.title || 'นัดหมายใหม่').trim();
  var rawLocation = data.location && data.location !== '-' ? String(data.location).trim() : '';
  var location = rawLocation || '-';
