  var startDtStr = String(data.datetime || '').trim();

  // คำนวณวันเวลา เริ่มต้น - สิ้นสุด
  var startDate = parseThaiDateTime(startDtStr);
  var endDate;
  if (data.endDatetime) {
    endDate = parseThaiDateTime(data.endDatetime);
    if (endDate <= startDate) {
      endDate = new Date(startDate.getTime() + (60 * 60 * 1000));
    }
  } else {
    endDate = new Date(startDate.getTime() + (60 * 60 * 1000));
  }

  // สร้าง Internal Event ID
  var eventId = data.eventId || ('natdee_' + generateUUIDv4());

