  var icsDownloadUrl = 'https://natdee.21missionboss.online/webhook/calendar-ics?id=' + encodeURIComponent(eventId) + '&action=add&openExternalBrowser=1';

  return {
    json: {
      userId: data.userId || '',
      replyToken: data.replyToken || '',
      event: eventTitle,
      datetime: startDtStr,
      endDatetime: data.endDatetime || '',
      location: location,
      category: category,
      eventId: eventId,
      mapsUrl: mapsUrl,
      icsDownloadUrl: icsDownloadUrl
    }
  };
});

